const ownerNext=!!document.querySelector('.portal-body');
function revisionSummary(o){const p=o.proposal;if(p?.state!=='awaiting-customer')return '';return `<section class="order-proposal"><h4>Review a basket change</h4><p>${escape(p.note)}</p><ul>${p.items.map(i=>`<li>${escape(i.name)} × ${i.qty} · ${money(i.price*i.qty)}</li>`).join('')}</ul><b>New total ${money(p.total)}</b><p class="form-note">Includes ${o.fulfillment==='pickup'?'free pickup':money(p.deliveryFee)+' delivery'}. Nothing changes until you approve.</p>${ownerNext?'<small>Waiting for customer approval before acceptance.</small>':`<button class="primary" data-revision="${escape(o.id)}" data-approve="yes">Approve · ${money(p.total)}</button><button data-revision="${escape(o.id)}" data-approve="no">Decline & cancel order</button>`}</section>`}
if(ownerNext){
 const oldAdminPayment=window.WCAdminPayment;window.WCAdminPayment=o=>oldAdminPayment(o)+revisionSummary(o)+(o.status==='Pending confirmation'&&o.paymentStatus==='Unpaid'?`<button class="portal-button" data-propose="${escape(o.id)}">Adjust items / suggest replacement</button>`:'')+(o.fulfillment==='delivery'?`<a class="map-link" target="_blank" rel="noopener noreferrer" href="${escape(WCNext.mapURL(o.address+' '+o.pin,true))}">⌖ Open delivery address in Google Maps ↗</a>`:'');
}else{
 const oldOrderPayment=window.WCOrderPayment;window.WCOrderPayment=o=>oldOrderPayment(o)+revisionSummary(o)+(o.status==='Pending confirmation'&&o.paymentStatus==='Unpaid'?`<button class="text-button" data-cancel-order="${escape(o.id)}">Cancel before store acceptance</button>`:'')+(o.status==='Rejected'?`<p class="form-note">${o.paymentStatus==='Refund required'?'Refund owed: '+money(o.total)+'. Contact the store to arrange it.':o.paymentStatus==='Refunded'?'Refund recorded by the store. Check your bank or cash receipt.':'Order cancelled. If you sent money, contact the store for a bank check.'}</p>`:'');
}
function proposeItems(id){const o=orders.find(o=>o.id===id);if(!o||!allowed())return;const initial=o.items.map(i=>({...i,qty:i.qty}));showModal(`<h2>Check the basket together.</h2><p class="form-note">Set unavailable item quantity to zero. Optionally suggest one replacement. The customer must approve the revised bill before you can accept.</p><form id="proposeitems">${initial.map(i=>`<label class="revision-row"><span>${escape(i.name)}</span><input name="qty-${i.id}" aria-label="Revised quantity for ${escape(i.name)}" required type="number" min="0" max="${i.qty}" step="1" value="${i.qty}"></label>`).join('')}<label>Optional replacement<select name="replacement"><option value="">No replacement</option>${products.filter(p=>!initial.some(i=>i.id===p.id)&&p.stock>0).map(p=>`<option value="${p.id}">${escape(p.name)} · ${money(p.price)}</option>`).join('')}</select></label><label>Replacement quantity<input name="replacementQty" type="number" min="1" max="100" step="1" value="1"></label><label>Explain the change<textarea name="note" required minlength="3" maxlength="200" placeholder="One item is unavailable. Here is an alternative for you to review."></textarea></label><button class="primary wide">Send revised basket for approval</button></form>`);$('#proposeitems').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),items=initial.map(i=>({id:i.id,qty:Number(data['qty-'+i.id])})).filter(i=>i.qty>0);if(data.replacement)items.push({id:Number(data.replacement),qty:Number(data.replacementQty)});const button=e.target.querySelector('button');button.disabled=true;try{await window.WKCloud.proposeOrderChange({id,items,note:data.note});$('#modal').close();notify('Sent for customer approval.')}catch(err){notify(err.message);button.disabled=false}}}
document.addEventListener('click',async event=>{
 const propose=event.target.closest('[data-propose]');if(propose&&ownerNext)return proposeItems(propose.dataset.propose);
 const revision=event.target.closest('[data-revision]');if(revision&&!ownerNext){const o=orders.find(o=>o.id===revision.dataset.revision);if(!o?.proposal)return;revision.disabled=true;try{await window.WKCloud.respondOrderChange({id:o.id,proposalId:o.proposal.id,accept:revision.dataset.approve==='yes',expectedTotal:o.proposal.total});notify(revision.dataset.approve==='yes'?'Basket approved. The store can now accept.':'Order cancelled and stock released.')}catch(e){notify(e.message);revision.disabled=false}}
 const cancel=event.target.closest('[data-cancel-order]');if(cancel&&!ownerNext){const id=cancel.dataset.cancelOrder;commerceModal('cancel-confirm',`<h2>Cancel this order?</h2><p>The store has not accepted it yet. Your reserved items will be released.</p><button class="primary wide" id="confirmcancel">Yes, cancel order</button><button class="text-button wide" id="keeporder">Keep my order</button>`);$('#keeporder').onclick=showCustomerOrders;$('#confirmcancel').onclick=async e=>{e.target.disabled=true;try{await window.WKCloud.cancelOrder(id);showCustomerOrders();notify('Order cancelled')}catch(err){notify(err.message);e.target.disabled=false}}}
});
